/**
 * ==================================
 * # Chamadas relacionadas a documentos
 * ==================================
 */

export async function getLinkedCedenteEsteiras(cedenteId: string): Promise<LinkedCedenteEsteira[]> {
    const res = await api.get(`/api/cedentes/${cedenteId}/esteiras/`);
    return res.data;
}

export async function getDocsFromEsteira(esteiraId: number): Promise<EsteiraDocs[]> {
    const res = await directApi.get(`/api/esteiras/${esteiraId}/documentos/`);
    return res.data;
}

