'use client';

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { QueryKeys } from '@/constants/query-keys';
import { getActiveEsteiraId } from '@/functions/broker/verifyActiveEsteira';
import {
    useCedenteLinkedEsteirasQuery,
    useExtratoCedenteDataQuery,
} from '@/hooks/queries/cedentes';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { getDocsFromEsteira } from '@/services/BrokerServices';
import { useBrokerStore } from '@/store/useBroker';
import { EsteiraDocs } from '@/types/broker';

export function usePropostaReviewEsteiraDocuments(extratoId: string | null | undefined) {
    const activeCedenteId = useBrokerStore((store) => store.activeCedente?.id);

    const { data: detailsExtratoData } = useQuery({
        ...useExtratoDataQueryOptions(extratoId ?? ''),
        enabled: Boolean(extratoId),
    });
    const { data: cedenteData } = useExtratoCedenteDataQuery(activeCedenteId);
    const { data: linkedEsteirasCedente, isLoading: isLoadingLinkedCedente } =
        useCedenteLinkedEsteirasQuery(activeCedenteId);
    const { data: linkedEsteirasRepresentante, isLoading: isLoadingLinkedRepresentante } =
        useCedenteLinkedEsteirasQuery(cedenteData?.representante_legal?.id);

    const oficioEsteirasAtivas = detailsExtratoData?.esteira_documentos_por_cedente;

    const activeCedenteEsteiraId = useMemo(
        () => getActiveEsteiraId(linkedEsteirasCedente, oficioEsteirasAtivas),
        [linkedEsteirasCedente, oficioEsteirasAtivas],
    );

    const activeRepresentanteEsteiraId = useMemo(
        () => getActiveEsteiraId(linkedEsteirasRepresentante, oficioEsteirasAtivas),
        [linkedEsteirasRepresentante, oficioEsteirasAtivas],
    );

    const { data: esteiraDocsCedente, isLoading: isLoadingDocsCedente } = useQuery<EsteiraDocs[]>({
        queryKey: [QueryKeys.broker.details.cedenteDocsData, activeCedenteId, activeCedenteEsteiraId],
        queryFn: () => getDocsFromEsteira(activeCedenteEsteiraId!),
        enabled: Boolean(linkedEsteirasCedente?.length && activeCedenteEsteiraId),
    });

    const { data: esteiraDocsRepresentante, isLoading: isLoadingDocsRepresentante } = useQuery<
        EsteiraDocs[]
    >({
        queryKey: [
            QueryKeys.broker.details.representateDocsData,
            cedenteData?.representante_legal?.id,
            activeRepresentanteEsteiraId,
        ],
        queryFn: () => getDocsFromEsteira(activeRepresentanteEsteiraId!),
        enabled: Boolean(linkedEsteirasRepresentante?.length && activeRepresentanteEsteiraId),
    });

    const documents = useMemo(() => {
        const merged = [...(esteiraDocsCedente ?? []), ...(esteiraDocsRepresentante ?? [])];
        const byId = new Map<number, EsteiraDocs>();
        for (const doc of merged) {
            if (doc.has_file && doc.download_url) {
                byId.set(doc.id, doc);
            }
        }
        return Array.from(byId.values());
    }, [esteiraDocsCedente, esteiraDocsRepresentante]);

    const isLoading =
        isLoadingLinkedCedente ||
        isLoadingLinkedRepresentante ||
        isLoadingDocsCedente ||
        isLoadingDocsRepresentante;

    return { documents, isLoading };
}

