/**
 * Fluxo canônico Dashboard2: documentos do cedente vêm da esteira (API broker),
 * alinhado ao broker (`DocsSliderContext` + `getDocsFromEsteira`).
 *
 * Entry points:
 * - `applyLeadApiDocsToShell` — hidratação inicial do GET /api/leads/:id/
 * - `syncLeadCedenteDocsFromEsteira` — fetch/reconcile com a esteira ativa
 */
import { getDocsFromEsteira, getEsteiraExigenciasCondicionais } from '@/services/BrokerServices';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import {
    DASHBOARD2_CEDENTE_DOCS_CHANGED_EVENT,
    dashboard2GetCanonicalCedentes,
    dashboard2LeadDocsNeedEsteiraSync,
    dashboard2LeadHasFetchableEsteira,
    dashboard2MergeEsteiraApiDocsIntoDocsCedente,
    dashboard2RemapDocsCedenteRelationIds,
    dashboard2ResolveCedenteEsteiraId,
    shouldApplyIncomingDocsCedente,
    type Dashboard2DocsCedenteRow,
    type Dashboard2EsteiraDocRow,
    type Dashboard2EsteiraExigenciaCondicional,
} from './dashboard2-cedente-doc-map';

export interface SyncLeadCedenteDocsOptions {
    force?: boolean;
    onUpdated?: () => void;
    onPersist?: () => void;
}

interface CedenteEsteiraTarget {
    relationId: string;
    esteiraId: number;
    isPj: boolean;
    representedPjRelationId: string | null;
}

function normalizeCedenteId(value: unknown): string {
    return String(value || '').trim();
}

function findRepresentedPjRelationId(item: any, cedentesVinculados: any[]): string | null {
    if (item?.cedente?.tipo !== 'PF') return null;

    const cedenteId = normalizeCedenteId(item?.cedente?.id);
    const linkedByRepresentative = cedentesVinculados.find((linked: any) => {
        const representanteId = normalizeCedenteId(linked?.cedente?.representante_legal?.id);
        return linked?.cedente?.tipo === 'PJ' && representanteId && representanteId === cedenteId;
    });
    if (linkedByRepresentative?.relation_id) return String(linkedByRepresentative.relation_id);

    const percentual = Number(item?.percentual_cessao || 0);
    if (percentual !== 0) return null;

    const fallbackPj = cedentesVinculados.find((linked: any) => linked?.cedente?.tipo === 'PJ');
    return fallbackPj?.relation_id ? String(fallbackPj.relation_id) : null;
}

function shouldAttachDocToRepresentedPj(doc: Dashboard2DocsCedenteRow): boolean {
    return doc?.tipoId === 'oficio_requisitorio'
        || String(doc?.tipo || '').toUpperCase() === 'OFICIO_REQUISITORIO';
}

export function buildCedenteEsteiraTargets(lead: any): CedenteEsteiraTarget[] {
    const cedentes = dashboard2GetCanonicalCedentes(lead);
    return cedentes
        .filter((item) => dashboard2ResolveCedenteEsteiraId(item, lead) != null && item?.relation_id)
        .map((item) => ({
            relationId: String(item.relation_id),
            esteiraId: dashboard2ResolveCedenteEsteiraId(item, lead)!,
            isPj: item?.cedente?.tipo === 'PJ',
            representedPjRelationId: findRepresentedPjRelationId(item, cedentes),
        }));
}

function resolveLeadIsPj(lead: any): boolean {
    const docDigits = String(lead?.cpf || '').replace(/\D/g, '');
    return String(lead?.especie || '').toLowerCase().includes('jurídica') || docDigits.length > 11;
}

function dispatchDocsChanged(): void {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new CustomEvent(DASHBOARD2_CEDENTE_DOCS_CHANGED_EVENT));
}

/** Hidrata docs do snapshot CRM sem apagar estado já sincronizado da esteira. */
export function applyLeadApiDocsToShell(
    shell: any,
    docPack: Record<string, unknown> | null | undefined,
): void {
    if (!docPack || typeof docPack !== 'object' || Array.isArray(docPack)) return;

    shell._documentacao_cedente_crm_full = { ...docPack };

    const cc = docPack.cadastro_completo;
    if (cc && typeof cc === 'object' && !Array.isArray(cc)) {
        shell.cadastroCompleto = { ...(cc as Record<string, unknown>) };
    }

    if (dashboard2LeadHasFetchableEsteira(shell)) {
        return;
    }

    if (Array.isArray(docPack.docs)) {
        const incoming = docPack.docs as Dashboard2DocsCedenteRow[];
        const existing = Array.isArray(shell.docsCedente) ? shell.docsCedente as Dashboard2DocsCedenteRow[] : [];
        if (shouldApplyIncomingDocsCedente(existing, incoming)) {
            shell.docsCedente = incoming;
        }
    }

    if (Array.isArray(shell.docsCedente) && shell.docsCedente.length > 0) {
        shell.docsCedente = dashboard2RemapDocsCedenteRelationIds(
            shell.docsCedente as Dashboard2DocsCedenteRow[],
            shell,
        );
    }
}

async function fetchDocsForTargets(
    lead: any,
    targets: CedenteEsteiraTarget[],
    existingDocs: Dashboard2DocsCedenteRow[],
): Promise<{ docs: Dashboard2DocsCedenteRow[]; exigencias: Dashboard2EsteiraExigenciaCondicional[] }> {
    const byEsteira = new Map<number, CedenteEsteiraTarget[]>();
    for (const target of targets) {
        const bucket = byEsteira.get(target.esteiraId) || [];
        bucket.push(target);
        byEsteira.set(target.esteiraId, bucket);
    }

    const docsByCedente: Dashboard2DocsCedenteRow[] = [];
    const exigenciasById = new Map<number, Dashboard2EsteiraExigenciaCondicional>();

    for (const [esteiraId, group] of Array.from(byEsteira.entries())) {
        const [rows, exigencias] = await Promise.all([
            getDocsFromEsteira(esteiraId) as Promise<Dashboard2EsteiraDocRow[]>,
            getEsteiraExigenciasCondicionais(esteiraId),
        ]);
        for (const exigencia of exigencias) {
            if (exigencia?.ativa) exigenciasById.set(exigencia.id, exigencia);
        }
        for (const target of group) {
            const existingForCedente = existingDocs.filter(
                (doc) => String(doc.relation_id || '') === target.relationId,
            );
            const merged = dashboard2MergeEsteiraApiDocsIntoDocsCedente(rows, target.isPj, existingForCedente);
            for (const doc of merged) {
                docsByCedente.push({
                    ...doc,
                    relation_id: target.representedPjRelationId && shouldAttachDocToRepresentedPj(doc)
                        ? target.representedPjRelationId
                        : target.relationId,
                });
            }
        }
    }

    const managedRelationIds = new Set(targets.map((target) => target.relationId));
    const unmanagedDocs = existingDocs.filter((doc) => {
        if (!doc.relation_id) return true;
        return !managedRelationIds.has(String(doc.relation_id));
    });

    return {
        docs: dashboard2RemapDocsCedenteRelationIds([...unmanagedDocs, ...docsByCedente], lead),
        exigencias: Array.from(exigenciasById.values()),
    };
}

async function fetchDocsFallbackCrmEsteira(
    lead: any,
): Promise<{ docs: Dashboard2DocsCedenteRow[]; exigencias: Dashboard2EsteiraExigenciaCondicional[] }> {
    const eid = Number(lead?.crm_kyc_esteira_id);
    if (!Number.isFinite(eid) || eid <= 0) {
        return {
            docs: Array.isArray(lead.docsCedente) ? lead.docsCedente : [],
            exigencias: Array.isArray(lead._exigenciasCondicionais) ? lead._exigenciasCondicionais : [],
        };
    }

    const cedentes = dashboard2GetCanonicalCedentes(lead);
    const defaultRelationId = cedentes[0]?.relation_id ? String(cedentes[0].relation_id) : 'principal';
    const existing = Array.isArray(lead.docsCedente) ? lead.docsCedente as Dashboard2DocsCedenteRow[] : [];
    const [rows, exigencias] = await Promise.all([
        getDocsFromEsteira(eid) as Promise<Dashboard2EsteiraDocRow[]>,
        getEsteiraExigenciasCondicionais(eid),
    ]);

    return {
        docs: dashboard2RemapDocsCedenteRelationIds(
            dashboard2MergeEsteiraApiDocsIntoDocsCedente(rows, resolveLeadIsPj(lead), existing).map((doc) => ({
                ...doc,
                relation_id: doc.relation_id ?? defaultRelationId,
            })),
            lead,
        ),
        exigencias: exigencias.filter((exigencia) => exigencia?.ativa),
    };
}

const inflightByLead = new Map<string, Promise<void>>();
const generationByLead = new Map<string, number>();

/**
 * Sincroniza `lead.docsCedente` com a esteira ativa (1 GET por esteiraId).
 * Único orquestrador — não duplicar fetch em seções/componentes filhos.
 */
export async function syncLeadCedenteDocsFromEsteira(
    lead: any,
    options: SyncLeadCedenteDocsOptions = {},
): Promise<void> {
    if (!dashboard2LeadHasFetchableEsteira(lead)) {
        return;
    }

    if (!options.force && !dashboard2LeadDocsNeedEsteiraSync(lead)) {
        return;
    }

    const leadKey = String(lead.id || 'anonymous');
    const inflight = inflightByLead.get(leadKey);
    if (inflight && !options.force) {
        return inflight;
    }

    const generation = (generationByLead.get(leadKey) || 0) + 1;
    generationByLead.set(leadKey, generation);

    const task = (async () => {
        try {
            const existingDocs = Array.isArray(lead.docsCedente) ? lead.docsCedente as Dashboard2DocsCedenteRow[] : [];
            const targets = buildCedenteEsteiraTargets(lead);
            const result = targets.length > 0
                ? await fetchDocsForTargets(lead, targets, existingDocs)
                : await fetchDocsFallbackCrmEsteira(lead);

            if (generationByLead.get(leadKey) !== generation) return;

            lead.docsCedente = result.docs;
            lead._exigenciasCondicionais = result.exigencias;
            options.onUpdated?.();
            dispatchDocsChanged();
            options.onPersist?.();
        } catch {
            sendToastMessage({
                type: 'error',
                title: 'Não foi possível carregar os documentos da esteira.',
            });
        }
    })();

    inflightByLead.set(leadKey, task);
    try {
        await task;
    } finally {
        if (inflightByLead.get(leadKey) === task) {
            inflightByLead.delete(leadKey);
        }
    }
}

