    type Dashboard2EsteiraDocRow,
} from './dashboard2-cedente-doc-map';

interface CedenteDocsSectionProps {
    esteiraId: number;
    isPj: boolean;
    leadId?: string;
    onDocsChange?: () => void;
}

const SLOTS_REP = [
    { id: 'identidade', label: 'Identidade', tipo: 'RG' },
    {
        id: 'certidao',
        label: 'Certidão Nasc./Casamento',
        tipo: 'CERTIDAO_NASCIMENTO_CASAMENTO',
    },
    { id: 'comprovante_res', label: 'Comprovante de Residência', tipo: 'COMPROVANTE_DE_RESIDENCIA' },
] as const;

const SLOTS_PJ_MAIN = [{ id: 'contrato_social', label: 'Contrato Social', tipo: 'CONTRATO_SOCIAL' }] as const;

function isPdf(doc: Dashboard2DocsCedenteRow): boolean {
    const ct = String(doc.content_type || '').toLowerCase();
    if (ct.includes('pdf')) return true;
    return /\.pdf$/i.test(String(doc.nome || ''));
}

function isImage(doc: Dashboard2DocsCedenteRow): boolean {
    const ct = String(doc.content_type || '').toLowerCase();
    if (ct.includes('image') || ct.includes('jpeg') || ct.includes('png') || ct.includes('webp')) return true;
    return /\.(jpe?g|png|webp|gif)$/i.test(String(doc.nome || ''));
}

function EsteiraDocActions({ doc }: { doc: Dashboard2DocsCedenteRow }) {
    const [pdfOpen, setPdfOpen] = useState(false);
    const [imgOpen, setImgOpen] = useState(false);

    const rawUrl = doc.download_url;
    if (!rawUrl) return null;
    const url: string = rawUrl;

    const nome = doc.display_name || doc.nome || 'documento';
    const looksPdf = isPdf(doc);
    const looksImg = isImage(doc);

    async function handleDownload(ev?: React.MouseEvent<HTMLButtonElement>) {
        if (ev && typeof ev.stopPropagation === 'function') ev.stopPropagation();
        try {
            await downloadFile({
                download_url: url,
                nome,
                content_type: doc.content_type || 'application/octet-stream',
            });
        } catch {
            sendToastMessage({ type: 'error', title: 'Não foi possível baixar o arquivo.' });
        }
    }

    function handleView(ev: React.MouseEvent<HTMLButtonElement>) {
        ev.stopPropagation();
        if (looksPdf) {
            setPdfOpen(true);
            return;
        }
        if (looksImg) {
            setImgOpen(true);
            return;
        }
        void handleDownload();
    }

    const btnBase = {
        padding: '2px 6px',
        borderRadius: 4,
        border: '1px solid var(--border)',
        background: 'var(--bg-base)',
        fontSize: 9,
        fontWeight: 600,
        cursor: 'pointer',
        fontFamily: 'var(--font-body)',
    } as const;

    return (
        <>
            <button type="button" onClick={handleView} style={{ ...btnBase, color: 'var(--accent)' }}>
                <span style={{ display: 'inline-flex', alignItems: 'center', gap: 3 }}>
                    <Eye size={11} strokeWidth={2} aria-hidden />
                    Ver
                </span>
            </button>
            <button type="button" onClick={handleDownload} style={{ ...btnBase, color: 'var(--text-secondary)' }}>
                <span style={{ display: 'inline-flex', alignItems: 'center', gap: 3 }}>
                    <Download size={11} strokeWidth={2} aria-hidden />
                    Baixar
                </span>
            </button>
            <PDFViewerModal open={pdfOpen} onOpenChange={setPdfOpen} fileUrl={url} fileName={nome} />
            {imgOpen ? (
                <ImgDocVisualizer
                    onClose={() => setImgOpen(false)}
                    url={url}
                    fileName={nome}
                />
            ) : null}
        </>
    );
}

function supportError(leadId?: string) {
    sendToastMessage({
        type: 'error',
        title: 'Erro ao preparar documentos do representante.',
        description: `Tente novamente. Se persistir, abra um Chamado no módulo de Suporte (menu lateral > Suporte > Novo Chamado) e informe o lead ${leadId || 'atual'}.`,
    });
}

export function CedenteDocsSection({ esteiraId, isPj, leadId, onDocsChange }: CedenteDocsSectionProps) {
    const [docs, setDocs] = useState<Dashboard2DocsCedenteRow[]>([]);
    const [loading, setLoading] = useState(false);
    const [outroDocTituloDraft, setOutroDocTituloDraft] = useState('');
    const [leadDocsSeed, setLeadDocsSeed] = useState<Dashboard2DocsCedenteRow[]>([]);
    const inputRef = useRef<HTMLInputElement | null>(null);
    const slotRef = useRef<string | null>(null);

    const slots = useMemo(() => (isPj ? SLOTS_PJ_MAIN : SLOTS_REP), [isPj]);

    useEffect(() => {
        let cancelled = false;
        if (!leadId) {
            setLeadDocsSeed([]);
            return () => {
                cancelled = true;
            };
        }

        void (async () => {
            try {
                const lead = await getLeadById(leadId);
                const rawDocs = lead?.documentacao_cedente_crm?.docs;
                if (!cancelled && Array.isArray(rawDocs)) {
                    setLeadDocsSeed(rawDocs as Dashboard2DocsCedenteRow[]);
                } else if (!cancelled) {
                    setLeadDocsSeed([]);
                }
            } catch {
                if (!cancelled) setLeadDocsSeed([]);
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [leadId]);

    const refetch = useCallback(async () => {
        setLoading(true);
        try {
            const rows = await getDocsFromEsteira(esteiraId);
            const merged = dashboard2MergeEsteiraApiDocsIntoDocsCedente(
                rows as Dashboard2EsteiraDocRow[],
                isPj,
                leadDocsSeed,
            );
            setDocs(merged);
            onDocsChange?.();
        } catch {
            supportError(leadId);
        } finally {
            setLoading(false);
        }
    }, [esteiraId, isPj, leadDocsSeed, leadId, onDocsChange]);

    useEffect(() => {
        void refetch();
    }, [refetch]);

    const extras = docs.filter(
        (d) => d.tipoId == null || !slots.some((slot) => slot.id === d.tipoId),
    );

    async function handleUpload(file: File, slotId: string | null) {
        const fd = new FormData();
        fd.append('arquivo', file);
        const nome = slotId ? file.name : outroDocTituloDraft.trim() || file.name;
        fd.append('nome', nome);
        fd.append('tipo', slotId ? dashboard2ResolveDocumentoTipoForSlot(slotId) : 'OUTROS');
        fd.append('data_documento', new Date().toISOString().slice(0, 10));
        fd.append('status', 'PENDENTE');

        try {
            await uploadDocumentToEsteira(esteiraId, fd);
            sendToastMessage({ type: 'success', title: 'Documento enviado.' });
            setOutroDocTituloDraft('');
            await refetch();
        } catch {
            supportError(leadId);
        }
    }

    async function handleDelete(id?: number) {
        if (!id) return;
        try {
            await deleteDocument(id);
            sendToastMessage({ type: 'success', title: 'Documento removido.' });
            await refetch();
        } catch {
            supportError(leadId);
        }
    }

    return (
        <div style={{ marginTop: 6 }}>
            {loading ? (
                <div style={{ fontSize: 10, color: 'var(--text-muted)' }}>Carregando documentos...</div>
            ) : null}

            <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginBottom: 8 }}>
                {slots.map((slot) => {
                    const attached = docs.find((d) => dashboard2DocMatchesSlot(d, slot.id));
                    return (
                        <div
                            key={slot.id}
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: 8,
                                padding: '7px 10px',
                                borderRadius: 7,
                                background: attached ? '#ecfdf5' : 'var(--bg-subtle)',
                                border: attached ? '1px solid #a7f3d0' : '1px solid var(--border)',
                            }}
                        >
                            <div
                                style={{
                                    width: 18,
                                    height: 18,
                                    borderRadius: 4,
                                    flexShrink: 0,
                                    border: attached ? '2px solid #059669' : '2px solid var(--border)',
                                    background: attached ? '#059669' : 'var(--bg-base)',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                }}
                            >
                                {attached ? <Check size={10} color="#fff" /> : null}
                            </div>

                            <div style={{ flex: 1, minWidth: 0 }}>
                                <div
                                    style={{
                                        fontSize: 11,
                                        fontWeight: attached ? 700 : 500,
                                        color: attached ? '#059669' : 'var(--text-secondary)',
                                    }}
                                >
                                    {slot.label}
                                </div>
                                {attached ? (
                                    <div
                                        style={{
                                            fontSize: 9,
                                            color: '#6b7280',
                                            fontFamily: 'var(--font-mono)',
                                        }}
                                    >
                                        {attached.nome} · {attached.data}
                                    </div>
                                ) : null}
                            </div>

                            {attached ? (
                                <div
                                    style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: 4,
                                        flexShrink: 0,
                                        flexWrap: 'wrap',
                                    }}
                                >
                                    {attached.download_url ? <EsteiraDocActions doc={attached} /> : null}
                                    <button
                                        type="button"
                                        onClick={() => void handleDelete(attached.api_documento_id)}
                                        style={{
                                            background: 'none',
                                            border: 'none',
                                            color: '#94a3b8',
                                            cursor: 'pointer',
                                            fontSize: 11,
                                            padding: '0 2px',
                                        }}
                                    >
                                        ×
                                    </button>
                                </div>
                            ) : (
                                <button
                                    type="button"
                                    onClick={() => {
                                        slotRef.current = slot.id;
                                        inputRef.current?.click();
                                    }}
                                    style={{
                                        padding: '3px 8px',
                                        borderRadius: 5,
                                        border: '1px dashed var(--border)',
                                        background: 'var(--bg-base)',
                                        color: 'var(--accent)',
                                        fontSize: 9,
                                        fontWeight: 600,
                                        cursor: 'pointer',
                                        fontFamily: 'var(--font-body)',
                                    }}
                                >
                                    + Anexar
                                </button>
                            )}
                        </div>
                    );
                })}
            </div>

            {extras.length > 0 ? (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 3, marginBottom: 6 }}>
                    {extras.map((d, i) => (
                        <div
                            key={`extra-${d.api_documento_id ?? i}`}
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: 6,
                                padding: '6px 10px',
                                borderRadius: 6,
                                background: 'var(--bg-subtle)',
                                border: '1px solid var(--border)',
                            }}
                        >
                            <Paperclip size={12} strokeWidth={2} aria-hidden style={{ color: 'var(--text-muted)' }} />
                            <span style={{ flex: 1, fontSize: 11, fontWeight: 600, color: 'var(--text-primary)' }}>
                                {d.display_name || d.nome}
                            </span>
                            <span style={{ fontSize: 9, fontFamily: 'var(--font-mono)', color: 'var(--text-muted)' }}>
                                {d.data}
                            </span>
                            {d.download_url ? <EsteiraDocActions doc={d} /> : null}
                            <button
                                type="button"
                                onClick={() => void handleDelete(d.api_documento_id)}
                                style={{
                                    background: 'none',
                                    border: 'none',
                                    color: 'var(--text-muted)',
                                    cursor: 'pointer',
                                    fontSize: 11,
                                    padding: '0 2px',
                                }}
                            >
                                ×
                            </button>
                        </div>
                    ))}
                </div>
            ) : null}

            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 6 }}>
                <input
                    value={outroDocTituloDraft}
                    onChange={(e) => setOutroDocTituloDraft(e.target.value)}
                    placeholder="Título do documento"
                    style={{
                        flex: 1,
                        fontSize: 10,
                        padding: '6px 8px',
                        borderRadius: 6,
                        border: '1px solid var(--border)',
                        fontFamily: 'var(--font-body)',
                    }}
                />
                <button
                    type="button"
                    onClick={() => {
                        if (!outroDocTituloDraft.trim()) {
                            sendToastMessage({ type: 'warning', title: 'Informe um título para o documento.' });
                            return;
                        }
                        slotRef.current = null;
                        inputRef.current?.click();
                    }}
                    style={{
                        padding: '6px 8px',
                        borderRadius: 6,
                        border: '1px dashed var(--border)',
                        background: 'var(--bg-base)',
                        color: 'var(--accent)',
                        fontSize: 9,
                        fontWeight: 700,
                        cursor: 'pointer',
                        fontFamily: 'var(--font-body)',
                        whiteSpace: 'nowrap',
                    }}
                >
                    + Outro documento
                </button>
            </div>

            <input
                ref={inputRef}
                type="file"
                className="hidden"
                onChange={(e) => {
                    const file = e.target.files?.[0];
                    e.currentTarget.value = '';
                    if (!file) return;
                    void handleUpload(file, slotRef.current);
                }}
            />
        </div>
    );
}

