import { CommonBadge } from '@/components/Badges/CommonBadge';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { QueryKeys } from '@/constants/query-keys';
import { downloadFile } from '@/functions/downloadFile';
import { getDocsFromEsteira, getLinkedCedenteEsteiras } from '@/services/BrokerServices';
import { CedenteDataProps, EsteiraDocs, LinkedCedenteEsteira } from '@/types/broker';
import { DetailedOficioProps } from '@/types/oficio';
import { useQuery } from '@tanstack/react-query';
import { ArrowBigDownDash, FileX2, SquareArrowOutUpLeft } from 'lucide-react';
import Image from 'next/image';
import { useMemo, useState } from 'react';

// ==============
// # SVG imports
// ==============
import { pjDocs } from '@/app/crm/broker/[id]/_components/DocumentsSection';
import { Button } from '@/components/Button';
import { ErrorMessageBox } from '@/components/ErrorMessage/ErrorMessageBox';
import ImgDocVisualizer from '@/components/Modals/BrokersDocs/ImgDocVizualizer';
import { PDFViewerModal } from '@/components/Modals/PDFViewerModal';
import JuridicoDetailsCedenteDocsViewerSkeleton from '@/components/Skeletons/Juridico/JuridicoDetailsCedenteDocsViewerSkeleton';
import { findEsteiraDocByTipo } from '@/functions/broker/findEsteiraDocByTipo';
import { getActiveEsteiraId } from '@/functions/broker/verifyActiveEsteira';
import IMGIcon from '../../../../public/images/icon/icon-img.svg';
import PDFIcon from '../../../../public/images/icon/icon-pdf.svg';

export function JuridicoDetailsCedenteDocsViewer({
    extratoData,
    cedenteInfo,
    cedenteType,
}: {
    extratoData: DetailedOficioProps;
    cedenteInfo: CedenteDataProps | undefined;
    cedenteType: 'PJ' | 'PF' | 'ES';
}) {
    // ==================
    // # React Query
    // ==================

    // Query para esteiras do cedente
    const {
        data: linkedCedenteEsteiraData,
        isLoading: isLoadingLinkedCedente,
        isFetching: isFetchingLinkedCedente,
        error: errorLinkedCedente,
        refetch: refetchLinkedCedenteEsteira,
    } = useQuery<LinkedCedenteEsteira[]>({
        queryKey: [
            QueryKeys.cedentes.linkedEsteirasCedente,
            extratoData.due_diligence[0].id,
            cedenteInfo?.id,
        ],
        queryFn: () => getLinkedCedenteEsteiras(cedenteInfo?.id as string),
        enabled: !!cedenteInfo?.id,
    });

    // Query para esteiras do representante legal, se houver
    const {
        data: linkedRepresentanteEsteiraData,
        isLoading: isLoadingLinkedRepresentante,
        isFetching: isFetchingLinkedRepresentante,
        error: errorLinkedRepresentante,
        refetch: refetchLinkedRepresentanteEsteira,
    } = useQuery<LinkedCedenteEsteira[]>({
        queryKey: [
            QueryKeys.cedentes.linkedEsteirasRepresentante,
            extratoData.due_diligence[0].id,
            cedenteInfo?.representante_legal?.id,
        ],
        queryFn: () => getLinkedCedenteEsteiras(cedenteInfo?.representante_legal?.id as string),
        enabled: !!cedenteInfo?.representante_legal?.id,
    });

    // Query para documentos da esteira do cedente
    const {
        data: linkedCedenteDocsData,
        isLoading: isLoadingLinkedCedenteDocs,
        isFetching: isFetchingLinkedCedenteDocs,
        error: errorLinkedCedenteDocs,
        refetch: refetchLinkedCedenteDocs,
    } = useQuery<EsteiraDocs[]>({
        queryKey: [
            QueryKeys.broker.details.cedenteDocsData,
            extratoData.due_diligence[0].id,
            cedenteInfo?.id,
        ],
        queryFn: () => getDocsFromEsteira(activeCedenteEsteiraId as number),
        enabled: !!linkedCedenteEsteiraData,
    });

    // Query para documentos da esteira do representante (se houver)
    const {
        data: linkedRepresentanteDocsData,
        isLoading: isLoadingLinkedRepresentanteDocs,
        isFetching: isFetchingLinkedRepresentanteDocs,
        error: errorLinkedRepresentanteDocs,
        refetch: refetchLinkedRepresentanteDocs,
    } = useQuery<EsteiraDocs[]>({
        queryKey: [
            QueryKeys.broker.details.representateDocsData,
            extratoData.due_diligence[0].id,
            cedenteInfo?.id,
        ],
        queryFn: () => getDocsFromEsteira(activeRepresentanteEsteiraId as number),
        enabled: !!linkedRepresentanteEsteiraData,
    });

    const [isDownloading, setIsDownloading] = useState<string | null>(null);
    const [isPDFModalOpen, setIsPDFModalOpen] = useState<boolean>(false);
    const [isImgVignetteOpen, setIsImgVignetteOpen] = useState<boolean>(false);
    const [document, setDocument] = useState<EsteiraDocs | null>(null);

    const extratoActiveEsteiras = extratoData.esteira_documentos_por_cedente;
    const filteredPfDocsByTipo = useMemo(() => {
        if (extratoData.tipo_do_oficio === 'CREDITÓRIO') {
            return linkedCedenteDocsData?.filter((doc) => doc.nome !== 'Ofício Requisitório');
        }
        return linkedCedenteDocsData;
    }, [extratoData, linkedCedenteDocsData]);

    const activeCedenteEsteiraId = useMemo(() => {
        const esteiraId = getActiveEsteiraId(linkedCedenteEsteiraData, extratoActiveEsteiras);
        return esteiraId ?? linkedCedenteEsteiraData?.[0].id;
    }, [linkedCedenteEsteiraData]);

    const activeRepresentanteEsteiraId = useMemo(() => {
        const esteiraId = getActiveEsteiraId(linkedRepresentanteEsteiraData, extratoActiveEsteiras);
        return esteiraId ?? linkedRepresentanteEsteiraData?.[0]?.id;
    }, [linkedRepresentanteEsteiraData]);

    // Função para encontrar documento por tipo
    const findDocumentByType = findEsteiraDocByTipo;

    async function handleDownloadDoc(document: {
        download_url: string;
        nome: string;
        content_type: string;
    }) {
        setIsDownloading(document.nome);
        await downloadFile(document);
        setIsDownloading(null);
    }

    function generateStatusColor(status: string | undefined) {
        switch (status) {
            case 'APROVADO':
                return 'green';
            case 'PENDENTE':
                return 'yellow';
            case 'REJEITADO':
                return 'red';
            default:
                return 'grey';
        }
    }

    function handleOpenVisualizationModal(document: EsteiraDocs | null) {
        setDocument(document);

        if (document?.content_type.includes('/pdf')) {
            setIsPDFModalOpen(true);
        } else {
            setIsImgVignetteOpen(true);
        }
    }

    function returnRetryFunctionByError() {
        if (errorLinkedCedente) {
            return refetchLinkedCedenteEsteira;
        } else if (errorLinkedRepresentante) {
            return refetchLinkedRepresentanteEsteira;
        } else if (errorLinkedCedenteDocs) {
            return refetchLinkedCedenteDocs;
        } else {
            return refetchLinkedRepresentanteDocs;
        }
    }

    if (
        errorLinkedCedenteDocs ||
        errorLinkedRepresentanteDocs ||
        errorLinkedCedente ||
        errorLinkedRepresentante
    ) {
        const retryFn = returnRetryFunctionByError();
        return (
            <ErrorMessageBox className="border-0 bg-transparent shadow-none" retryFn={retryFn} />
        );
    }

    if (
        isLoadingLinkedCedente ||
        isLoadingLinkedCedenteDocs ||
        isFetchingLinkedCedente ||
        isFetchingLinkedCedenteDocs ||
        isLoadingLinkedRepresentante ||
        isFetchingLinkedRepresentante ||
        isLoadingLinkedRepresentanteDocs ||
        isFetchingLinkedRepresentanteDocs
    ) {
        return <JuridicoDetailsCedenteDocsViewerSkeleton />;
    }

    return (
        <>
            <h2 className="mb-6 font-medium text-subtitle">Documentos Relacionados</h2>
            <Table className="rounded-md border border-stroke dark:border-form-strokedark">
                <TableHeader>
                    <TableRow className="bg-boxdark-2 hover:bg-boxdark-2 dark:hover:bg-boxdark-2">
                        <TableHead>Nome do Documento</TableHead>
                        <TableHead className="w-[120px]">Status</TableHead>
                        <TableHead className="w-[130px]">Ações</TableHead>
                    </TableRow>
                </TableHeader>
                <TableBody>
                    {cedenteType === 'PJ' && (
                        <>
                            {pjDocs.map((doc) => {
                                const document = findDocumentByType(
                                    linkedCedenteDocsData || [],
                                    doc.type,
                                );
                                const docStatusColor = generateStatusColor(document?.status);

                                return (
                                    <TableRow key={`doc-${doc.name}`}>
                                        <TableCell className="flex h-[64.4px] items-center gap-3 text-paragraph">
                                            {document ? (
                                                <Image
                                                    src={
                                                        document?.content_type.endsWith('/pdf')
                                                            ? PDFIcon
                                                            : IMGIcon
                                                    }
                                                    alt="doc-icon"
                                                    width={24}
                                                    height={24}
                                                />
                                            ) : (
                                                <FileX2 size={24} className="text-paragraph" />
                                            )}
                                            <span className="text-sm">{doc.name}</span>
                                        </TableCell>
                                        <TableCell>
                                            <div className="mx-auto w-fit">
                                                <CommonBadge
                                                    options={{
                                                        info: {
                                                            name: document?.status,
                                                            color: docStatusColor,
                                                        },
                                                        dot: true,
                                                    }}
                                                />
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex items-center">
                                                <Button
                                                    variant={'ghost'}
                                                    isLoading={isDownloading === document?.nome}
                                                    disabled={!document?.download_url}
                                                    className="flex items-center justify-center gap-2 rounded-md px-3 py-1.5 transition-colors duration-300 hover:bg-blue-100 hover:text-blue-600 disabled:hover:bg-transparent disabled:hover:text-inherit dark:hover:bg-blue-950/60 dark:hover:text-blue-400"
                                                    onClick={() =>
                                                        handleDownloadDoc({
                                                            download_url:
                                                                document?.download_url as string,
                                                            nome: document?.nome as string,
                                                            content_type:
                                                                document?.content_type as string,
                                                        })
                                                    }
                                                >
                                                    <ArrowBigDownDash size={16} />
                                                    <span className="text-sm">Baixar</span>
                                                </Button>
                                                <Button
                                                    variant={'ghost'}
                                                    disabled={!document?.download_url}
                                                    className="flex items-center justify-center gap-2 rounded-md px-3 py-1.5 transition-colors duration-300 hover:bg-green-100 hover:text-green-600 disabled:hover:bg-transparent disabled:hover:text-inherit dark:hover:bg-green-950/60 dark:hover:text-green-400"
                                                    onClick={() =>
                                                        handleOpenVisualizationModal(document)
                                                    }
                                                >
                                                    <SquareArrowOutUpLeft size={16} />
                                                    <span className="text-sm">Visualizar</span>
                                                </Button>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                );
                            })}

                            {linkedRepresentanteDocsData?.map((document) => {
                                const docStatusColor = generateStatusColor(document?.status);
                                return (
                                    <TableRow key={`doc-rep-${document.id}`}>
                                        <TableCell className="flex h-[64.4px] items-center gap-3 text-paragraph">
                                            {document ? (
                                                <Image
                                                    src={
                                                        document?.content_type.endsWith('/pdf')
                                                            ? PDFIcon
                                                            : IMGIcon
                                                    }
                                                    alt="doc-icon"
                                                    width={24}
                                                    height={24}
                                                />
                                            ) : (
                                                <FileX2 size={24} className="text-paragraph" />
                                            )}
                                            <span className="text-sm">{document.nome}</span>
                                        </TableCell>
                                        <TableCell>
                                            <div className="mx-auto w-fit">
                                                <CommonBadge
                                                    options={{
                                                        info: {
                                                            name: document?.status,
                                                            color: docStatusColor,
                                                        },
                                                        dot: true,
                                                    }}
                                                />
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex items-center">
                                                <Button
                                                    variant={'ghost'}
                                                    isLoading={isDownloading === document?.nome}
                                                    disabled={!document?.download_url}
                                                    className="flex items-center justify-center gap-2 rounded-md px-3 py-1.5 transition-colors duration-300 hover:bg-blue-100 hover:text-blue-600 disabled:hover:bg-transparent disabled:hover:text-inherit dark:hover:bg-blue-950/60 dark:hover:text-blue-400"
                                                    onClick={() =>
                                                        handleDownloadDoc({
                                                            download_url:
                                                                document?.download_url as string,
                                                            nome: document?.nome as string,
                                                            content_type:
                                                                document?.content_type as string,
                                                        })
                                                    }
                                                >
