                                                        className="flex items-center justify-center gap-2 rounded-md px-3 py-1.5 transition-colors duration-300 hover:bg-green-100 hover:text-green-600 disabled:hover:bg-transparent disabled:hover:text-inherit dark:hover:bg-green-950/60 dark:hover:text-green-400"
                                                        onClick={() =>
                                                            handleOpenVisualizationModal(document)
                                                        }
                                                    >
                                                        <SquareArrowOutUpLeft size={16} />
                                                        <span className="text-sm">Visualizar</span>
                                                    </Button>
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    );
                                })}
                        </>
                    )}

                    {cedenteType === 'PF' && (
                        <>
                            {filteredPfDocsByTipo?.map((document) => {
                                const docStatusColor = generateStatusColor(document?.status);
                                return (
                                    <TableRow
                                        key={`doc-${document.id}`}
                                        className="hover:bg-transparent dark:hover:bg-transparent"
                                    >
                                        <TableCell className="flex h-[64.4px] items-center gap-3 text-paragraph">
                                            {document ? (
                                                <Image
                                                    src={
                                                        document?.content_type.endsWith('/pdf')
                                                            ? PDFIcon
                                                            : IMGIcon
                                                    }
                                                    alt="doc-icon"
                                                    width={24}
                                                    height={24}
                                                />
