                                                    disabled={!document?.download_url}
                                                    className="flex items-center justify-center gap-2 rounded-md px-3 py-1.5 transition-colors duration-300 hover:bg-blue-100 hover:text-blue-600 disabled:hover:bg-transparent disabled:hover:text-inherit dark:hover:bg-blue-950/60 dark:hover:text-blue-400"
                                                    onClick={() =>
                                                        handleDownloadDoc({
                                                            download_url:
                                                                document?.download_url as string,
                                                            nome: document?.nome as string,
                                                            content_type:
                                                                document?.content_type as string,
                                                        })
                                                    }
                                                >
                                                    <ArrowBigDownDash size={16} />
                                                    <span className="text-sm">Baixar</span>
                                                </Button>
                                                <Button
                                                    variant={'ghost'}
                                                    disabled={!document?.download_url}
                                                    className="flex items-center justify-center gap-2 rounded-md px-3 py-1.5 transition-colors duration-300 hover:bg-green-100 hover:text-green-600 disabled:hover:bg-transparent disabled:hover:text-inherit dark:hover:bg-green-950/60 dark:hover:text-green-400"
                                                    onClick={() =>
                                                        handleOpenVisualizationModal(document)
                                                    }
                                                >
                                                    <SquareArrowOutUpLeft size={16} />
                                                    <span className="text-sm">Visualizar</span>
                                                </Button>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                );
                            })}
                        </>
                    )}
                </TableBody>
            </Table>

            <PDFViewerModal
                fileUrl={document?.download_url || ''}
                open={isPDFModalOpen}
                onOpenChange={setIsPDFModalOpen}
                fileName={document?.nome || ''}
            />
            {isImgVignetteOpen && (
                <ImgDocVisualizer
                    onClose={() => setIsImgVignetteOpen(false)}
                    url={document?.download_url || ''}
                    fileName={document?.nome || ''}
                />
            )}
        </>
    );
}

