'use client';

import { DETALHES_PARTE_PATCH_DEBOUNCE_MS } from '@/constants/due-diligence';
import { QueryKeys } from '@/constants/query-keys';
import { getActiveEsteiraId } from '@/functions/broker/verifyActiveEsteira';
import { debounce } from '@/functions/debounce';
import { useDocumentPreview } from '@/functions/hooks/use-document-preview';
import { useUpdateDetalhesPartePessoaMutation } from '@/hooks/mutations/due-diligence';
import {
    useEsteiraDocumentoMutations,
    type TDeleteEsteiraDocumentoMutationVariables,
    type TUploadEsteiraDocumentoMutationVariables,
} from '@/hooks/mutations/esteira-documentos';
import { useCedenteLinkedEsteirasQuery } from '@/hooks/queries/cedentes';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { getDocsFromEsteira } from '@/services/BrokerServices';
import type { EsteiraDocs } from '@/types/broker';
import { Filter } from '@/types/filter';
import type { OficioEsteiraResumo } from '@/types/oficio';
import { useQuery } from '@tanstack/react-query';
import { parseAsString, parseAsStringLiteral, useQueryState } from 'nuqs';
import { useCallback, useEffect, useMemo, useRef } from 'react';
import { useForm } from 'react-hook-form';
import type {
    ICertidoesService,
    IDetalhesParteVinculadaService,
    IRelatorioProcessualService,
    ISituacaoJuridicaService,
} from '../../interfaces/services';
import {
    DETALHES_PARTE_NAO_INFORMADO,
    EMPTY_DETALHES_PARTE_FORM_VALUES,
    TITULAR_TIPO_VALUES,
    type TDetalhesParteCadastroFormField,
    type TDetalhesParteDadosBancariosUpdateField,
    type TDetalhesParteFormValues,
    type TDetalhesParteUpdateField,
    type TTipoParte,
} from '../../types/detalhesParteVinculada';
import type { TCertidoesPorEntidade } from '../../types/dueItem';
import { EMPTY_PENDENCIA_LISTAGEM } from '../../types/pendencia';
import {
    convertTemplateToCertidoesFormat,
    mergeCertidoesPorEntidade,
    partitionCertidoesByTipo,
    resolvePadraoCertidaoId,
} from '../../utils/certidoes';
import { dueDiligenceDetailQueryKey } from '../../utils/invalidate-due-caches';
import {
    EMPTY_DETALHES_PARTE_DOC_SLOTS,
    resolveDetalhesParteDocSlots,
    resolveDetalhesParteExtraDocs,
    type TDetalhesParteDocSlotUploadMetaMap,
} from '../../utils/mapDetalhesParteEsteiraDocs';
import { isTitularTipo } from '../../utils/mapTitularProcessos';
import { normalizeDetalhesPartePessoa } from '../../utils/normalizeDetalhesPartePessoa';
import {
    collectCertidaoIdsComPendencia,
    collectProcessoIdsComPendencia,
} from '../../utils/pendenciaHelpers';

export const DETALHES_PARTE_TIPO_PARTE_AUSENTE_MESSAGE =
    'Parâmetro tipoParte ausente. Tente novamente com o parâmetro correto.' as const;

export const DETALHES_PARTE_CERTIDOES_EMPTY_MESSAGE =
    'Nenhuma certidão encontrada para esta parte.' as const;

export const DETALHES_PARTE_PROCESSOS_EMPTY_MESSAGE =
    'Nenhum processo no polo passivo vinculado a esta pessoa.' as const;

const PROCESSOS_POLO_PASSIVO_FILTERS: Filter[] = [
    {
        id: 'polo',
        label: 'Polo',
        value: 'passivo',
    },
];

export interface IUseViewModelDetalhesParteParams {
    dueId: string;
    parteId: string;
    detalhesParteService: IDetalhesParteVinculadaService;
    certidoesService: ICertidoesService;
    relatorioProcessualService: IRelatorioProcessualService;
    situacaoJuridicaService: ISituacaoJuridicaService;
}

export function useViewModelDetalhesParte({
    dueId,
    parteId,
    detalhesParteService,
    certidoesService,
    relatorioProcessualService,
    situacaoJuridicaService,
}: IUseViewModelDetalhesParteParams) {
    const [tipoParte] = useQueryState('tipoParte', parseAsStringLiteral(TITULAR_TIPO_VALUES));
    const [extratoId] = useQueryState('extratoId', parseAsString);

    const {
        pdfViewer,
        imgViewer: imagemPreview,
        openPreview,
        onPdfOpenChange: handlePdfOpenChange,
        closeImgViewer: handleCloseImagePreview,
    } = useDocumentPreview();

    const isTipoParteValid = isTitularTipo(tipoParte);
    const tipoTitular: TTipoParte | null = isTipoParteValid ? tipoParte : null;
    const isTipoParteParamError = !isTipoParteValid;
    const canFetchByParte = Boolean(dueId) && Boolean(parteId) && isTipoParteValid;
    const updateTipoParte = tipoTitular ?? 'cedente';

    const { mutate: updateDetalhesPartePessoa } = useUpdateDetalhesPartePessoaMutation({
        dueId,
        parteId,
        tipoParte: updateTipoParte,
        service: detalhesParteService,
    });

    const debouncedUpdateByFieldRef = useRef<
        Map<
            TDetalhesParteUpdateField,
            ReturnType<typeof debounce<(value: string | null) => void>>
        >
    >(new Map());

    const debouncedUpdateDadoBancarioByFieldRef = useRef<
        Map<
            TDetalhesParteDadosBancariosUpdateField,
            ReturnType<typeof debounce<(value: string | null) => void>>
        >
    >(new Map());

    const {
        data: pessoaApiResult,
        isLoading: isPessoaLoading,
        isError: isPessoaError,
        isFetching: isPessoaFetching,
    } = useQuery({
        queryKey: [QueryKeys.dueDiligence.detalhesPartePessoa, dueId, parteId, tipoParte],
        queryFn: () => {
            if (!isTitularTipo(tipoParte)) {
                throw new Error('tipoParte inválido para busca da pessoa');
            }
            return detalhesParteService.fetchPessoa(parteId, tipoParte);
        },
        enabled: canFetchByParte,
    });

    const pessoaData = useMemo(
        () => (pessoaApiResult ? normalizeDetalhesPartePessoa(pessoaApiResult) : null),
        [pessoaApiResult],
    );

    const canFetchSecondary = canFetchByParte && !!pessoaData;
    const canFetchEsteira =
        canFetchSecondary && tipoParte === 'cedente' && Boolean(extratoId);

    const { data: dueDetail, isFetching: isDueDetailFetching } = useQuery({
        queryKey: dueDiligenceDetailQueryKey(dueId),
        queryFn: () => situacaoJuridicaService.fetchDetail(dueId),
        enabled: canFetchSecondary,
    });

    const form = useForm<TDetalhesParteFormValues>({
        defaultValues: EMPTY_DETALHES_PARTE_FORM_VALUES,
    });

    const hasAppliedFormDefaultsRef = useRef(false);

    useEffect(() => {
        if (!pessoaData || hasAppliedFormDefaultsRef.current) return;

        form.reset(pessoaData.formValues);
        hasAppliedFormDefaultsRef.current = true;
    }, [pessoaData, form]);

    const resolveUpdateField = useCallback(
        (field: TDetalhesParteCadastroFormField): TDetalhesParteUpdateField => {
            if (field === 'documento') {
                return pessoaData?.documentoTipo === 'CNPJ' ? 'cnpj' : 'cpf';
            }

            if (field === 'nome' && pessoaData?.isPessoaJuridica) {
                return 'razao_social';
            }

            return field;
        },
        [pessoaData],
    );

    const { data: certidoesTemplates, isLoading: isLoadingCertidoesTemplates } = useQuery({
        queryKey: [QueryKeys.dueDiligence.certidoesTemplates],
        queryFn: () => certidoesService.fetchCertidoesTemplates(),
        enabled: canFetchSecondary,
    });

    const padraoAtivoId = useMemo(() => {
        if (!pessoaData) return 0;
        return resolvePadraoCertidaoId(pessoaData.padraoCertidao, certidoesTemplates);
    }, [pessoaData, certidoesTemplates]);

    const hasPadraoResolvido = padraoAtivoId > 0;

    const {
        data: certidoesDataRemote,
        isLoading: isCertidoesQueryLoading,
        isError: isCertidoesError,
        isFetching: isCertidoesFetching,
    } = useQuery({
        queryKey: [
            QueryKeys.dueDiligence.pessoaCertidoes,
            dueId,
            parteId,
            tipoParte,
            padraoAtivoId,
        ],
        queryFn: () => certidoesService.fetchCertidoes(dueId, parteId, padraoAtivoId),
        enabled: canFetchSecondary && hasPadraoResolvido,
    });

    const {
        data: processosDataRemote,
        isLoading: isProcessosQueryLoading,
        isError: isProcessosError,
        isFetching: isProcessosFetching,
    } = useQuery({
        queryKey: [
            QueryKeys.dueDiligence.pessoaProcessos,
            dueId,
            parteId,
            tipoParte,
            PROCESSOS_POLO_PASSIVO_FILTERS,
        ],
        queryFn: () =>
            relatorioProcessualService.getProcessos(
                dueId,
                parteId,
                PROCESSOS_POLO_PASSIVO_FILTERS,
            ),
        enabled: canFetchSecondary,
    });

    const {
        data: pessoaParecerRemote,
        isLoading: isParecerQueryLoading,
        isError: isParecerError,
        isFetching: isParecerFetching,
    } = useQuery({
        queryKey: [QueryKeys.dueDiligence.pessoaParecer, parteId],
        queryFn: () => situacaoJuridicaService.fetchPessoaParecer(parteId),
        enabled: canFetchSecondary,
    });

    const {
        data: linkedEsteirasCedente,
        isLoading: isLinkedEsteirasLoading,
        isFetching: isLinkedEsteirasFetching,
    } = useCedenteLinkedEsteirasQuery(parteId, { enabled: canFetchEsteira });

    const {
        data: oficioEsteirasAtivas,
        isLoading: isOficioEsteirasLoading,
        isFetching: isOficioEsteirasFetching,
    } = useQuery({
        ...useExtratoDataQueryOptions(extratoId ?? ''),
        enabled: canFetchEsteira,
        select: (oficioData): OficioEsteiraResumo[] | undefined =>
            oficioData.esteira_documentos_por_cedente,
    });

    const activeEsteiraId = useMemo(() => {
        if (!canFetchEsteira) return null;
        return getActiveEsteiraId(linkedEsteirasCedente, oficioEsteirasAtivas);
    }, [canFetchEsteira, linkedEsteirasCedente, oficioEsteirasAtivas]);

    const {
        data: esteiraDocs = [],
        isLoading: isEsteiraDocsQueryLoading,
        isFetching: isEsteiraDocsFetching,
    } = useQuery<EsteiraDocs[]>({
        queryKey: [QueryKeys.broker.details.cedenteDocsData, parteId, activeEsteiraId],
        queryFn: () => getDocsFromEsteira(activeEsteiraId!),
        enabled: canFetchEsteira && !!activeEsteiraId,
    });

    const isCertidoesLoading =
        canFetchSecondary &&
        (isLoadingCertidoesTemplates || (hasPadraoResolvido && isCertidoesQueryLoading));

    const isProcessosLoading = canFetchSecondary && isProcessosQueryLoading;
    const isParecerLoading = canFetchSecondary && isParecerQueryLoading;

    const isEsteiraDocsLoading =
        canFetchEsteira &&
        (isLinkedEsteirasLoading ||
            isOficioEsteirasLoading ||
            (!!activeEsteiraId && isEsteiraDocsQueryLoading));

    const docSlots = useMemo(() => {
        if (!canFetchEsteira || !pessoaData) {
            return { ...EMPTY_DETALHES_PARTE_DOC_SLOTS };
        }

        return resolveDetalhesParteDocSlots(esteiraDocs, pessoaData.documentoTipo);
    }, [canFetchEsteira, esteiraDocs, pessoaData]);

    const extraDocs = useMemo(
        () => resolveDetalhesParteExtraDocs(esteiraDocs, docSlots),
        [docSlots, esteiraDocs],
    );

    const { uploadMutation, deleteMutation } = useEsteiraDocumentoMutations({
        parteId,
        esteiraId: activeEsteiraId,
    });

    const canManageDocumentos = Boolean(activeEsteiraId);

    const docSlotUploadMeta = useMemo<TDetalhesParteDocSlotUploadMetaMap>(() => {
        const isPessoaJuridica = pessoaData?.documentoTipo === 'CNPJ';

        return {
            identificacao: isPessoaJuridica
                ? { tipo: 'CONTRATO_SOCIAL', nome: 'Contrato Social' }
                : { tipo: 'RG', nome: 'Identidade (RG)' },
            certidaoNascimentoCasamento: {
                tipo: 'CERTIDAO_NASCIMENTO_CASAMENTO',
                nome: 'Certidão de Nascimento/Casamento',
            },
            comprovanteResidencia: {
                tipo: 'COMPROVANTE_DE_RESIDENCIA',
                nome: 'Comprovante de Residência',
            },
            comprovanteTitularidadeConta: {
                tipo: 'OUTROS',
                nome: 'Comprovante de titularidade da conta',
            },
        };
    }, [pessoaData?.documentoTipo]);

    const onUploadDocumento = useCallback(
        (variables: TUploadEsteiraDocumentoMutationVariables) => {
            if (!activeEsteiraId) return;
            uploadMutation.mutate(variables);
        },
        [activeEsteiraId, uploadMutation],
    );

    const onDeleteDocumento = useCallback(
        (variables: TDeleteEsteiraDocumentoMutationVariables) => {
            if (!activeEsteiraId) return;
            deleteMutation.mutate(variables);
        },
        [activeEsteiraId, deleteMutation],
    );

    const isDocSlotMutating = useCallback(
        (slotKey: string): boolean => {
            const uploadSlotKey =
                uploadMutation.variables?.slotKey ?? uploadMutation.variables?.tipo;
            const deleteSlotKey =
                deleteMutation.variables?.slotKey ?? deleteMutation.variables?.tipo;

            return (
                (uploadMutation.isPending && uploadSlotKey === slotKey) ||
                (deleteMutation.isPending && deleteSlotKey === slotKey)
            );
        },
        [
            uploadMutation.isPending,
            uploadMutation.variables,
            deleteMutation.isPending,
            deleteMutation.variables,
        ],
    );

    const certidoesPorEntidade = useMemo<TCertidoesPorEntidade>(() => {
        const certidoesRemote = certidoesDataRemote?.results ?? [];
        const templateAtivo = certidoesTemplates?.find((template) => template.id === padraoAtivoId);

        if (!templateAtivo) {
            return partitionCertidoesByTipo(certidoesRemote);
        }

        const baseTemplate = convertTemplateToCertidoesFormat(templateAtivo);
        return mergeCertidoesPorEntidade(baseTemplate, certidoesRemote);
    }, [certidoesDataRemote, certidoesTemplates, padraoAtivoId]);

    const certidoesData = useMemo(
        () => [...certidoesPorEntidade.fiscais, ...certidoesPorEntidade.processuais],
        [certidoesPorEntidade],
    );
    const processosData = useMemo(
        () =>
            (processosDataRemote?.results ?? []).filter(
                (processo) => processo.vinculado_a === 'pessoa',
            ),
        [processosDataRemote],
    );
    const pendenciasFonte = dueDetail?.pendencias ?? EMPTY_PENDENCIA_LISTAGEM;
    const certsEmPendencia = useMemo(
        () => collectCertidaoIdsComPendencia(pendenciasFonte, { onlyAbertas: true }),
        [pendenciasFonte],
    );
    const processosEmPendencia = useMemo(
        () => collectProcessoIdsComPendencia(pendenciasFonte, { onlyAbertas: true }),
        [pendenciasFonte],
    );
    const parecerCertidao = pessoaParecerRemote?.certidao ?? null;
    const parecerProcessos = pessoaParecerRemote?.processos ?? null;

    const onVisualizarDocumento = useCallback(
        (esteiraDoc: EsteiraDocs) => {
            void openPreview(esteiraDoc);
        },
        [openPreview],
    );

    const onUpdateCampoDigitavel = useCallback(
        (field: TDetalhesParteCadastroFormField, value: string | null) => {
            if (!isTipoParteValid) return;

            const updateField = resolveUpdateField(field);

            if (!debouncedUpdateByFieldRef.current.has(updateField)) {
                debouncedUpdateByFieldRef.current.set(
                    updateField,
                    debounce((nextValue: string | null) => {
                        updateDetalhesPartePessoa({
                            payload: { [updateField]: nextValue },
                        });
                    }, DETALHES_PARTE_PATCH_DEBOUNCE_MS),
                );
            }

            debouncedUpdateByFieldRef.current.get(updateField)?.(value);
        },
        [isTipoParteValid, resolveUpdateField, updateDetalhesPartePessoa],
    );

    const onUpdateCampoSelecionavel = useCallback(
        (field: TDetalhesParteCadastroFormField, value: string | null) => {
            if (!isTipoParteValid) return;

            updateDetalhesPartePessoa({
                payload: { [resolveUpdateField(field)]: value },
            });
        },
        [isTipoParteValid, resolveUpdateField, updateDetalhesPartePessoa],
    );

    const onUpdateDadoBancarioDigitavel = useCallback(
        (field: TDetalhesParteDadosBancariosUpdateField, value: string | null) => {
            if (!isTipoParteValid) return;

            if (!debouncedUpdateDadoBancarioByFieldRef.current.has(field)) {
                debouncedUpdateDadoBancarioByFieldRef.current.set(
                    field,
                    debounce((nextValue: string | null) => {
                        updateDetalhesPartePessoa({
                            payload: { informacoes_bancarias: { [field]: nextValue } },
                        });
                    }, DETALHES_PARTE_PATCH_DEBOUNCE_MS),
                );
            }

            debouncedUpdateDadoBancarioByFieldRef.current.get(field)?.(value);
        },
        [isTipoParteValid, updateDetalhesPartePessoa],
    );

    const onUpdateDadoBancarioSelecionavel = useCallback(
        (field: TDetalhesParteDadosBancariosUpdateField, value: string | null) => {
            if (!isTipoParteValid) return;

            updateDetalhesPartePessoa({
                payload: { informacoes_bancarias: { [field]: value } },
            });
        },
        [isTipoParteValid, updateDetalhesPartePessoa],
    );

    const isLoading = canFetchByParte && isPessoaLoading;

    const isFetching =
        isPessoaFetching ||
        isDueDetailFetching ||
        isCertidoesFetching ||
        isProcessosFetching ||
        isParecerFetching ||
        isLinkedEsteirasFetching ||
        isOficioEsteirasFetching ||
        isEsteiraDocsFetching;

    const isPessoaEmpty = canFetchByParte && !isPessoaLoading && !isPessoaError && !pessoaData;
    const isCertidoesEmpty =
        canFetchSecondary &&
        hasPadraoResolvido &&
        !isCertidoesLoading &&
        !isCertidoesError &&
        certidoesData.length === 0;
    const isProcessosEmpty =
        canFetchSecondary &&
        !isProcessosLoading &&
        !isProcessosError &&
        processosData.length === 0;

    return {
        ui: {
            dueId,
            parteId,
            tipoParte,
            tipoTitular,
            extratoId,
            isTipoParteParamError,
            tipoParteErrorMessage: isTipoParteParamError
                ? DETALHES_PARTE_TIPO_PARTE_AUSENTE_MESSAGE
                : null,
            pessoaData,
            certidoesData,
            certidoesPorEntidade,
            processosData,
            certsEmPendencia,
            processosEmPendencia,
            parecerCertidao,
            parecerProcessos,
            padraoAtivoId: hasPadraoResolvido ? padraoAtivoId : null,
            activeEsteiraId,
            esteiraDocs,
            docSlots,
            extraDocs,
            docSlotUploadMeta,
            canManageDocumentos,
            pdfViewer,
            imagemPreview,
            isLoading,
            isFetching,
            isPessoaLoading,
            isCertidoesLoading,
            isProcessosLoading,
            isParecerLoading,
            isEsteiraDocsLoading,
            isPessoaError,
            isCertidoesError,
            isProcessosError,
            isParecerError,
            isPessoaEmpty,
            isCertidoesEmpty,
            isProcessosEmpty,
        },
        form,
        handlers: {
            onUpdateCampoDigitavel,
            onUpdateCampoSelecionavel,
            onUpdateDadoBancarioDigitavel,
            onUpdateDadoBancarioSelecionavel,
            onVisualizarDocumento,
            onUploadDocumento,
            onDeleteDocumento,
            isDocSlotMutating,
            handlePdfOpenChange,
            handleCloseImagePreview,
        },
        constants: {
            tipoParteAusenteMessage: DETALHES_PARTE_TIPO_PARTE_AUSENTE_MESSAGE,
            certidoesEmptyMessage: DETALHES_PARTE_CERTIDOES_EMPTY_MESSAGE,
            processosEmptyMessage: DETALHES_PARTE_PROCESSOS_EMPTY_MESSAGE,
            naoInformadoLabel: DETALHES_PARTE_NAO_INFORMADO,
            processosPoloPassivoFilters: PROCESSOS_POLO_PASSIVO_FILTERS,
        },
    };
}

export type TDetalhesParteViewModel = ReturnType<typeof useViewModelDetalhesParte>;
export type TDetalhesParteUI = TDetalhesParteViewModel['ui'];
export type TDetalhesParteForm = TDetalhesParteViewModel['form'];
export type TDetalhesParteHandlers = TDetalhesParteViewModel['handlers'];
export type TDetalhesParteConstants = TDetalhesParteViewModel['constants'];

